<?php namespace App\Http\Controllers; use App\Models\{Campaign,Topic,PerformanceEntry,SignalCheck}; use Carbon\Carbon; class DashboardController{function __invoke(){ $tid=session('active_tenant_id'); $week=[now()->startOfWeek(),now()->endOfWeek()]; return view('dashboard.index',['planned'=>Campaign::where('tenant_id',$tid)->whereBetween('start_date',$week)->get(),'published'=>Campaign::where('tenant_id',$tid)->where('status','published')->whereBetween('start_date',[now()->subWeek()->startOfWeek(),now()->subWeek()->endOfWeek()])->get(),'topics'=>Topic::where('tenant_id',$tid)->whereIn('status',['active','prepare'])->get(),'performances'=>PerformanceEntry::where('tenant_id',$tid)->latest()->limit(5)->get(),'checks'=>SignalCheck::where('tenant_id',$tid)->latest()->limit(5)->get()]);}}
